<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $r=mysqli_query($conn,"SELECT p.id,p.name,SUM(oi.quantity) total_quantity,SUM(oi.quantity*oi.price) total_revenue FROM products p JOIN order_items oi ON p.id=oi.product_id GROUP BY p.id,p.name ORDER BY total_quantity DESC"); ?>
<h2>Best Selling Products</h2><div class="table-responsive"><table class="table table-bordered table-striped bg-white mt-3"><thead class="table-dark"><tr><th>Product ID</th><th>Product</th><th>Quantity Sold</th><th>Total Revenue</th></tr></thead><tbody><?php while($x=mysqli_fetch_assoc($r)): ?><tr><td><?php echo $x['id']; ?></td><td><?php echo htmlspecialchars($x['name']); ?></td><td><?php echo $x['total_quantity']; ?></td><td><?php echo number_format($x['total_revenue'],2); ?></td></tr><?php endwhile; ?></tbody></table></div><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>